<?php
require_once __DIR__ . '/../branches/_helpers.php';
require_once __DIR__ . '/../../../app/Modules/Marketplace/Marketplace.php';
function opname_db(): PDO { return Database::connect(); }
function opname_column_exists(PDO $db,string $table,string $column):bool{$s=$db->prepare("SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=? AND COLUMN_NAME=?");$s->execute([$table,$column]);return (int)$s->fetchColumn()>0;}
function opname_index_exists(PDO $db,string $table,string $index):bool{$s=$db->prepare("SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=? AND INDEX_NAME=?");$s->execute([$table,$index]);return (int)$s->fetchColumn()>0;}
function opname_ensure_tables(PDO $db):void{
 branch_install($db);marketplace_install($db);
 $db->exec("CREATE TABLE IF NOT EXISTS stock_opnames (id BIGINT AUTO_INCREMENT PRIMARY KEY,code VARCHAR(50) NOT NULL UNIQUE,title VARCHAR(180) NOT NULL,user_id BIGINT NULL,branch_id BIGINT NULL,status ENUM('draft','finalized','canceled') NOT NULL DEFAULT 'draft',total_items INT NOT NULL DEFAULT 0,total_checked INT NOT NULL DEFAULT 0,total_plus INT NOT NULL DEFAULT 0,total_minus INT NOT NULL DEFAULT 0,total_plus_value DECIMAL(15,2) NOT NULL DEFAULT 0,total_minus_value DECIMAL(15,2) NOT NULL DEFAULT 0,note TEXT NULL,finalized_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,INDEX idx_stock_opnames_status(status),INDEX idx_stock_opnames_created(created_at),INDEX idx_stock_opnames_branch(branch_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
 $db->exec("CREATE TABLE IF NOT EXISTS stock_opname_items (id BIGINT AUTO_INCREMENT PRIMARY KEY,opname_id BIGINT NOT NULL,product_id BIGINT NOT NULL,variant_id BIGINT NOT NULL DEFAULT 0,product_name VARCHAR(220) NOT NULL,variant_name VARCHAR(180) NULL,product_code VARCHAR(120) NULL,unit VARCHAR(40) NULL,system_stock INT NOT NULL DEFAULT 0,physical_stock INT NULL,difference INT NOT NULL DEFAULT 0,purchase_price DECIMAL(15,2) NOT NULL DEFAULT 0,selling_price DECIMAL(15,2) NOT NULL DEFAULT 0,difference_value DECIMAL(15,2) NOT NULL DEFAULT 0,reason VARCHAR(80) NULL,note TEXT NULL,adjusted_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uniq_opname_product_variant(opname_id,product_id,variant_id),INDEX idx_opname_items_opname(opname_id),INDEX idx_opname_items_product(product_id),INDEX idx_opname_items_variant(variant_id),INDEX idx_opname_items_diff(difference)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
 foreach([['stock_opnames','branch_id','BIGINT NULL AFTER user_id'],['stock_opnames','total_plus_value','DECIMAL(15,2) NOT NULL DEFAULT 0 AFTER total_minus'],['stock_opnames','total_minus_value','DECIMAL(15,2) NOT NULL DEFAULT 0 AFTER total_plus_value'],['stock_opname_items','variant_id','BIGINT NOT NULL DEFAULT 0 AFTER product_id'],['stock_opname_items','variant_name','VARCHAR(180) NULL AFTER product_name'],['stock_opname_items','purchase_price','DECIMAL(15,2) NOT NULL DEFAULT 0 AFTER difference'],['stock_opname_items','selling_price','DECIMAL(15,2) NOT NULL DEFAULT 0 AFTER purchase_price'],['stock_opname_items','difference_value','DECIMAL(15,2) NOT NULL DEFAULT 0 AFTER selling_price']] as $c){if(!opname_column_exists($db,$c[0],$c[1]))try{$db->exec("ALTER TABLE {$c[0]} ADD COLUMN {$c[1]} {$c[2]}");}catch(Throwable $e){}}
 try{if(opname_index_exists($db,'stock_opname_items','uniq_opname_product'))$db->exec('ALTER TABLE stock_opname_items DROP INDEX uniq_opname_product');}catch(Throwable $e){}
 try{if(!opname_index_exists($db,'stock_opname_items','uniq_opname_product_variant'))$db->exec('ALTER TABLE stock_opname_items ADD UNIQUE KEY uniq_opname_product_variant(opname_id,product_id,variant_id)');}catch(Throwable $e){}
 branch_install($db);marketplace_v16_install($db);
 try{$db->exec("UPDATE stock_opname_items soi JOIN products p ON p.id=soi.product_id SET soi.purchase_price=COALESCE(NULLIF(soi.purchase_price,0),p.purchase_price),soi.selling_price=COALESCE(NULLIF(soi.selling_price,0),p.selling_price),soi.difference_value=ABS(soi.difference)*COALESCE(NULLIF(soi.purchase_price,0),p.purchase_price,0) WHERE soi.purchase_price=0 OR soi.selling_price=0 OR soi.difference_value=0");}catch(Throwable $e){}
}
function opname_code(PDO $db):string{$prefix='OPN-'.date('Ymd').'-';$s=$db->prepare('SELECT code FROM stock_opnames WHERE code LIKE ? ORDER BY id DESC LIMIT 1');$s->execute([$prefix.'%']);$last=$s->fetchColumn();$next=1;if($last){$parts=explode('-',(string)$last);$next=((int)end($parts))+1;}return $prefix.str_pad((string)$next,4,'0',STR_PAD_LEFT);}
function opname_status_badge(string $status):string{if($status==='finalized')return '<span class="opname-badge success"><i class="bi bi-check-circle"></i> Final</span>';if($status==='canceled')return '<span class="opname-badge danger"><i class="bi bi-x-circle"></i> Batal</span>';return '<span class="opname-badge warning"><i class="bi bi-pencil-square"></i> Draft</span>';}
function opname_reason_label(?string $reason):string{$m=['match'=>'Sesuai','missing'=>'Hilang','damaged'=>'Rusak','expired'=>'Expired','wrong_input'=>'Salah Input','found'=>'Stok Lebih','other'=>'Lainnya'];return $m[$reason?:'']??'-';}
function opname_redirect(string $path):void{legacy_redirect($path);}
function opname_get(PDO $db,int $id):?array{$s=$db->prepare('SELECT so.*,u.name user_name,b.name branch_name FROM stock_opnames so LEFT JOIN users u ON u.id=so.user_id LEFT JOIN branches b ON b.id=so.branch_id WHERE so.id=? LIMIT 1');$s->execute([$id]);return $s->fetch()?:null;}
function opname_items(PDO $db,int $opnameId):array{$s=$db->prepare('SELECT soi.*,p.image FROM stock_opname_items soi LEFT JOIN products p ON p.id=soi.product_id WHERE soi.opname_id=? ORDER BY soi.product_name,soi.variant_name,soi.id');$s->execute([$opnameId]);return $s->fetchAll()?:[];}
function opname_sync_totals(PDO $db,int $opnameId):void{$s=$db->prepare("SELECT COUNT(*) total_items,SUM(CASE WHEN physical_stock IS NULL THEN 0 ELSE 1 END) total_checked,SUM(CASE WHEN difference>0 THEN difference ELSE 0 END) total_plus,SUM(CASE WHEN difference<0 THEN ABS(difference) ELSE 0 END) total_minus,SUM(CASE WHEN difference>0 THEN ABS(difference_value) ELSE 0 END) total_plus_value,SUM(CASE WHEN difference<0 THEN ABS(difference_value) ELSE 0 END) total_minus_value FROM stock_opname_items WHERE opname_id=?");$s->execute([$opnameId]);$r=$s->fetch()?:[];$u=$db->prepare('UPDATE stock_opnames SET total_items=?,total_checked=?,total_plus=?,total_minus=?,total_plus_value=?,total_minus_value=?,updated_at=NOW() WHERE id=?');$u->execute([(int)($r['total_items']??0),(int)($r['total_checked']??0),(int)($r['total_plus']??0),(int)($r['total_minus']??0),(float)($r['total_plus_value']??0),(float)($r['total_minus_value']??0),$opnameId]);}
function opname_branch_id(PDO $db,int $opnameId=0):int{if($opnameId>0){$s=$db->prepare('SELECT branch_id FROM stock_opnames WHERE id=?');$s->execute([$opnameId]);$id=(int)$s->fetchColumn();if($id>0)return $id;}return branch_current_id($db);}
function opname_seed_items(PDO $db,int $opnameId):void{
 $branchId=opname_branch_id($db,$opnameId);$products=$db->query("SELECT id,name,product_code,unit,stock,purchase_price,selling_price FROM products WHERE is_active=1 ORDER BY name,id")->fetchAll();
 $stmt=$db->prepare("INSERT IGNORE INTO stock_opname_items(opname_id,product_id,variant_id,product_name,variant_name,product_code,unit,system_stock,physical_stock,difference,purchase_price,selling_price,difference_value,reason,created_at) VALUES(?,?,?,?,?,?,?, ?,NULL,0,?,?,0,NULL,NOW())");
 foreach($products as $p){$vars=marketplace_v15_variants($db,(int)$p['id'],$branchId,true);if($vars){foreach($vars as $v){$label=trim((string)($v['display_name']??$v['name']));$stmt->execute([$opnameId,$p['id'],$v['id'],$p['name'].' - '.$label,$label,$v['sku']?:$p['product_code'],$p['unit'],(int)$v['stock'],(float)($v['purchase_price']?:$p['purchase_price']),(float)($v['selling_price']?:$p['selling_price'])]);}}else{$stock=(int)$p['stock'];try{$q=$db->prepare('SELECT stock FROM product_branch_stocks WHERE branch_id=? AND product_id=?');$q->execute([$branchId,$p['id']]);$x=$q->fetchColumn();if($x!==false)$stock=(int)$x;}catch(Throwable $e){}$stmt->execute([$opnameId,$p['id'],0,$p['name'],null,$p['product_code'],$p['unit'],$stock,(float)$p['purchase_price'],(float)$p['selling_price']]);}}
 opname_sync_totals($db,$opnameId);
}
?>
